@Injectable({ providedIn: 'root' })
export class TopicApi {
  private readonly http = inject(HttpClient);

  getTopic(id: string): Observable<Topic> {
    return this.http.get<Topic>(`/api/topics/${id}`);
  }
}

export const authGuard: CanActivateFn = () => {
  const session = inject(SessionService);
  const router = inject(Router);
  return session.isAuthenticated() ? true : router.parseUrl('/login');
};

// route config
{ path: 'settings', canActivate: [authGuard], loadComponent: () => import('./settings') }

profile = new FormGroup({
  email: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.email] }),
  bio: new FormControl(''),
});

constructor() {
  this.profile.controls.email.valueChanges
    .pipe(debounceTime(300), distinctUntilChanged())
    .subscribe(email => this.checkEmailAvailable(email));
}
